import { Theme } from "@types";
import { createTheme } from "@theme";
import { SelectClasses } from "@components/select";

import { MainNavClasses } from "../main-nav.styles";

export const createMainNavTheme = (theme: Theme): Theme => {
  const out = createTheme(theme, {
    focusRing: {
      ...theme.focusRingInverse,
    },
    componentVariants: {
      Accordion: {
        default: {
          root: {
            minWidth: 0,
          },
          header: {
            borderTop: "none",
            width: "100%",
            fontWeight: "normal",
            minHeight: theme.toRem(32),
          },
          buttonExpanded: {
            [`.${MainNavClasses.item}`]: {
              backgroundColor: "transparent",
              color: theme.mainNav.color,
            },
          },
          button: {
            padding: 0,
            minHeight: theme.toRem(32),
            borderRadius: theme.toRem(theme.border.radius.sm),
            height: "auto",
          },
          section: {
            backgroundColor: theme.mainNav.backgroundColor,
            transition: `background-color ${theme.mainNav.transitionDuration} ease-in-out`,
            paddingTop: theme.toRem(2),
            marginTop: theme.toRem(-2),
            borderRadius: theme.toRem(theme.border.radius.sm),
          },
          sectionExpanded: {
            backgroundColor: theme.mainNav.backgroundColorExpanded,
            borderRadius: theme.toRem(theme.border.radius.sm),
          },
          indicator: {
            width: "unset",
            color: theme.color.content.inverseStrong,
            transition: `transform ${theme.mainNav.transitionDuration} ease-in-out`,
            transform: "rotate(-90deg)",
          },
          indicatorExpanded: {
            transform: "rotate(0deg)",
          },
          contentContainer: {
            transition: `max-height ${theme.mainNav.transitionDuration} ease-in-out`,
          },
          contentInner: {
            padding: `${theme.toRem(2)} ${theme.toRem(8)} ${theme.toRem(8)} ${theme.toRem(8)}`,
            display: "flex",
            flexDirection: "column",
            gap: theme.toRem(2),
            [`.${MainNavClasses.item}`]: {
              paddingInlineStart: theme.toRem(24),
              "&:hover:not([data-main-nav-item-current])": {
                backgroundColor: theme.mainNav.accordionItemHighlighted,
              },
            },
            paddingInlineStart: theme.toRem(8),
          },
        },
      },
      Badge: {
        /**
         * @deprecated Use `MainNav.InlineBadge` instead. This variant will be removed in a future release.
         */
        mainNavItem: {
          root: {
            backgroundColor: theme.mainNav.badgeDefault,
            color: theme.mainNav.color,
          },
          roomy: {
            backgroundColor: theme.mainNav.badgeDefault,
            color: theme.mainNav.color,
          },
          dotLg: {
            backgroundColor: theme.mainNav.badgeDefault,
            color: theme.mainNav.color,
          },
          dotSm: {
            backgroundColor: theme.mainNav.badgeDefault,
            color: theme.mainNav.color,
          },
        },
        mainNavDot: {
          root: {
            backgroundColor: theme.mainNav.badgeDot,
            color: theme.mainNav.color,
          },
          roomy: {
            backgroundColor: theme.mainNav.badgeDot,
            color: theme.mainNav.color,
          },
          dotLg: {
            backgroundColor: theme.mainNav.badgeDot,
            color: theme.mainNav.color,
          },
          dotSm: {
            backgroundColor: theme.mainNav.badgeDot,
            color: theme.mainNav.color,
          },
        },
      },
      Divider: {
        default: {
          root: {
            margin: `${theme.toRem(8)} ${theme.toRem(8)}`,
            width: "fill-available !important",
            minHeight: theme.toRem(1),
            opacity: 0.25,
          },
          small: {
            backgroundColor: theme.color.brand.primary.ivory,
          },
          medium: {
            backgroundColor: theme.color.brand.primary.ivory,
          },
          large: {
            backgroundColor: theme.color.brand.primary.ivory,
          },
        },
      },
      Menu: {
        default: {
          content: {
            minWidth: theme.toRem(176),
            backgroundColor: theme.mainNav.backgroundColor,
            border: "none",
          },
          divider: {
            backgroundColor: theme.mainNav.menuDivider,
          },
          triggerOpen: {
            [`&.${MainNavClasses.item}:not(:hover)`]: {
              backgroundColor: "transparent",
              color: theme.mainNav.color,
            },
            "&:hover": {
              backgroundColor: theme.mainNav.menuItemHighlighted,
              color: theme.mainNav.color,
            },
          },
        },
        mainNavMenu: {
          content: {
            minWidth: theme.toRem(216),
            backgroundColor: theme.mainNav.backgroundColor,
            border: "none",
          },
          group: {
            padding: theme.toRem(theme.spacing[16]),
          },
          divider: {
            backgroundColor: theme.mainNav.menuDivider,
            margin: `0 ${theme.toRem(theme.spacing[16])}`,
          },
          triggerOpen: {
            [`&.${MainNavClasses.item}:not(:hover)`]: {
              backgroundColor: "transparent",
              color: theme.mainNav.color,
            },
            "&:hover": {
              backgroundColor: theme.mainNav.menuItemHighlighted,
              color: theme.mainNav.color,
            },
          },
        },
      },
      MenuItem: {
        default: {
          root: {
            color: theme.mainNav.color,
            backgroundColor: theme.mainNav.backgroundColor,
            height: theme.toRem(32),
            borderRadius: theme.toRem(theme.border.radius.sm),
            borderWidth: 0,
            ...theme.typography.label.md,
            lineHeight: theme.typography.lineHeight[20],
            "&[data-main-nav-item-current=true]": {
              backgroundColor: theme.mainNav.backgroundColorSelected,
              color: theme.mainNav.backgroundColor,
              "&:hover": {
                backgroundColor: theme.mainNav.backgroundColorSelected,
                color: theme.mainNav.backgroundColor,
              },
            },
          },
          label: {
            color: theme.mainNav.color,
          },
          hover: {
            backgroundColor: theme.mainNav.menuItemHighlighted,
            color: theme.mainNav.color,
          },
        },
        mainNavMenu: {
          root: {
            color: theme.mainNav.color,
            backgroundColor: theme.mainNav.backgroundColor,
            height: theme.toRem(32),
            borderRadius: theme.toRem(theme.border.radius.sm),
            borderWidth: 0,
            ...theme.typography.label.md,
            lineHeight: theme.typography.lineHeight[20],
            "&[data-main-nav-item-current=true]": {
              backgroundColor: theme.mainNav.backgroundColorSelected,
              color: theme.mainNav.backgroundColor,
              "&:hover": {
                backgroundColor: theme.mainNav.backgroundColorSelected,
                color: theme.mainNav.backgroundColor,
              },
            },
          },
          label: {
            color: theme.mainNav.color,
          },
          hover: {
            backgroundColor: theme.mainNav.menuItemHighlighted,
            color: theme.mainNav.color,
          },
        },
      },
      Select: {
        default: {
          root: {
            color: theme.mainNav.color,
            minWidth: 0,
            borderRadius: `calc(${theme.toRem(theme.border.radius.sm)} + ${theme.toRem(1)})`,
          },
          startAdornment: {
            color: theme.mainNav.color,
          },
          startAdornmentFocus: {
            color: theme.mainNav.color,
          },
          startAdornmentHover: {
            color: theme.mainNav.color,
          },
          trigger: {
            backgroundColor: theme.mainNav.selectTrigger,
            border: `${theme.toRem(theme.border.width.sm)} solid ${theme.mainNav.selectTriggerBorder}`,
            color: theme.mainNav.color,
            minWidth: 0,
            overflow: "hidden",
            transition: `width ${theme.mainNav.transitionDuration} ease`,
            padding: theme.toRem(8),
            height: theme.toRem(32),
          },
          triggerHover: {
            backgroundColor: theme.mainNav.selectTriggerHover,
            borderColor: theme.mainNav.selectTriggerBorderHover,
            color: theme.mainNav.color,
          },
          triggerFocus: {
            color: theme.mainNav.color,
            borderColor: theme.color.transparency.transparent,
          },
          triggerIcon: {
            color: theme.mainNav.color,
            paddingInlineStart: 0,
            width: "fit-content",
            minWidth: 0,
          },
          triggerIconHover: {
            color: theme.mainNav.color,
          },
          triggerIconFocus: {
            color: theme.mainNav.color,
          },
          label: {
            [`> .${SelectClasses.label}`]: {
              whiteSpace: "nowrap",
              overflow: "hidden",
              textOverflow: "ellipsis",
              maxWidth: theme.toRem(125),
              display: "block",
            },
          },
          content: {
            backgroundColor: theme.mainNav.backgroundColor,
            width: theme.toRem(200),
          },
          groupLabel: {
            backgroundColor: theme.mainNav.backgroundColor,
            color: theme.mainNav.selectGroupLabelBackground,
            padding: theme.toRem(8),
            fontSize: theme.typography.fontSize[10],
            fontWeight: theme.typography.fontWeight[700],
            lineHeight: theme.typography.lineHeight[16],
            letterSpacing: theme.typography.letterSpacing.sm,
          },
          item: {
            color: theme.mainNav.color,
            height: theme.toRem(32),
            borderRadius: theme.toRem(theme.border.radius.sm),
          },
          itemHighlighted: {
            backgroundColor: theme.mainNav.selectItemHighlighted,
            color: "unset",
          },
          divider: {
            backgroundColor: theme.mainNav.selectDivider,
          },
        },
      },
      Tooltip: {
        default: {
          root: {
            fontWeight: "normal",
          },
        },
      },
    },
  });

  return out;
};
